method Add(lst: seq<int>) returns (result: int)
    requires |lst| > 0 // the list must be non-empty
    ensures forall i :: 0 <= i < |lst| ==> (i % 2 == 1 && lst[i] % 2 == 0 ==> result == SumEvenAtOddIndices(lst))
{
    result := 0;
    var n := |lst|;
    var i := 1;
    while i < n
        invariant 0 <= i <= n
        invariant result == SumEvenAtOddIndices(lst[0..i])
    {
        if lst[i] % 2 == 0 {
            result := result + lst[i];
        }
        i := i + 2; // increment by 2 to check the next odd index
    }
}

function SumEvenAtOddIndices(lst: seq<int>): int
    reads lst
    ensures result == Sum(lst[i] | i % 2 == 1 && lst[i] % 2 == 0)
{
    if |lst| == 0 {
        return 0;
    } else {
        var sum := 0;
        var idx := 1;
        while idx < |lst|
            invariant 0 <= idx <= |lst|
            invariant sum == Sum(lst[i] | i < idx && i % 2 == 1 && lst[i] % 2 == 0)
        {
            if lst[idx] % 2 == 0 {
                sum := sum + lst[idx];
            }
            idx := idx + 2;
        }
        return sum;
    }
}
